/** Shared colors for the profile's self-contained SVG assets. */
export const palette = Object.freeze({
  black: '#0c0d0b',
  paper: '#e8e7df',
  red: '#ff4d35',
  acid: '#c8ff4d',
  muted: '#a5a99c',
  line: '#34372e',
});

export const width = 960;

export function escapeXml(value = '') {
  const entities = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' };
  return String(value).replace(/[&<>"']/g, character => entities[character]);
}

/** A complete SVG image; body/defs are trusted SVG generated by local scripts. */
export function svgDocument({ height, title, description = '', body = '', defs = '', background = palette.black, width: imageWidth = width }) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${imageWidth}" height="${height}" viewBox="0 0 ${imageWidth} ${height}" role="img" aria-labelledby="title description">
  <title id="title">${escapeXml(title)}</title>
  <desc id="description">${escapeXml(description)}</desc>
  ${defs ? `<defs>${defs}</defs>` : ''}
  <rect width="${imageWidth}" height="${height}" fill="${background}"/>
  ${body}
</svg>
`.replace(/[\t ]+$/gm, '');
}

export const svg = svgDocument;
